def compute(vars):
    subscriber_revenue = vars["v1"]
    traditional_revenue = vars["v2"]
    difference = subscriber_revenue - traditional_revenue

    return {
        "value": difference,
        "trace": {
            "subscriber_revenue": subscriber_revenue,
            "traditional_revenue": traditional_revenue,
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
